TizenActionView::ServiceBase::ServiceBase(std::string sender, std::string instance)
: sender_(std::move(sender)),
instance_(std::move(instance)) {
  SetPrivilegeMap();

  dispatch_funcs_ = {
    { static_cast<int>(MethodId::FindById), std::bind(&TizenActionView::ServiceBase::DispatchFindById, this, std::placeholders::_1, std::placeholders::_2, std::placeholders::_3, std::placeholders::_4) },
    { static_cast<int>(MethodId::GetAnnotatedViews), std::bind(&TizenActionView::ServiceBase::DispatchGetAnnotatedViews, this, std::placeholders::_1, std::placeholders::_2, std::placeholders::_3, std::placeholders::_4) },
    { static_cast<int>(MethodId::GetFocusedView), std::bind(&TizenActionView::ServiceBase::DispatchGetFocusedView, this, std::placeholders::_1, std::placeholders::_2, std::placeholders::_3, std::placeholders::_4) },
    { static_cast<int>(MethodId::ToPresentation), std::bind(&TizenActionView::ServiceBase::DispatchToPresentation, this, std::placeholders::_1, std::placeholders::_2, std::placeholders::_3, std::placeholders::_4) },
  };
}

void TizenActionView::ServiceBase::SetPort(rpc_port_h port) {
  port_ = port;

}

void TizenActionView::ServiceBase::Disconnect() {
  if (GetContext() != nullptr) {
    TizenActionView_context_->Disconnect(GetContext());
    SetContext(nullptr);
  } else {
    int ret = rpc_port_disconnect(port_);
    if (ret != RPC_PORT_ERROR_NONE) {
      _E("Failed to disconnect the port. error(%d)", ret);
      return;
    }
  }

  instance_.clear();
  port_ = nullptr;
}

int TizenActionView::ServiceBase::Dispatch(rpc_port_h port, rpc_port_h callback_port, rpc_port_parcel_h parcel, std::shared_ptr<ServiceBase> service) {
  return Dispatch(port, callback_port, parcel);

}

int TizenActionView::ServiceBase::Dispatch(rpc_port_h port, rpc_port_h callback_port, rpc_port_parcel_h parcel) {
  rpc_port_parcel_header_h header;
  rpc_port_parcel_get_header(parcel, &header);

  int seq_num = -1;
  rpc_port_parcel_header_get_seq_num(header, &seq_num);

  UnitMap unit_map_;
  unit_map_.Deserialize(parcel);

  int cmd_ = -1;
  unit_map_.Read(1355467489 /*[METHOD]*/, cmd_);

  auto found = dispatch_funcs_.find(cmd_);
  if (found == dispatch_funcs_.end()) {
    _E("Unknown command(%d)", cmd_);
    rpc_port_parcel_destroy(parcel);
    return -1;
  }

  auto& func = found->second;
  func(port, callback_port, seq_num, unit_map_);
  rpc_port_parcel_destroy(parcel);
  return 0;
}

void TizenActionView::ServiceBase::SetPrivilegeMap() {

}

void TizenActionView::ServiceBase::SetParent(const TizenActionView* parent) {
  parent_ = parent;
}

bool TizenActionView::ServiceBase::CheckPrivileges(rpc_port_h port, int method_id) {
  int ret;
  uid_t uid;
  pid_t pid;
  auto found = privilege_map_.find(method_id);
  if (found == privilege_map_.end())
    return true;

  ret = dl_rpc_port_get_peer_info(port, &pid, &uid);
  if(ret == RPC_PORT_ERROR_NONE && uid < kRegularUidMin) {
    _W("Bypass access control. pid(%d), uid(%u)", pid, uid);
    return true;
  }

  for (const auto& privilege : found->second) {
    bool has = false;

    ret = dl_rpc_port_stub_has_privilege_local(
    parent_->GetRaw(), GetSender().c_str(), privilege.c_str(), &has);
    if (ret != 0 || !has) {
      return false;
    }
  }

  return true;
}

void TizenActionView::ServiceBase::DispatchFindById(rpc_port_h port, rpc_port_h callback_port, int seq_num, const UnitMap& unit_map) {
  rpc_port_parcel_h parcel_;
  rpc_port_parcel_create(&parcel_);

  rpc_port_parcel_header_h header_;
  rpc_port_parcel_get_header(parcel_, &header_);
  rpc_port_parcel_header_set_seq_num(header_, seq_num);
  if (dl_rpc_port_parcel_header_set_tag_ex) {
    dl_rpc_port_parcel_header_set_tag_ex(header_, TIDL_VER_MAJOR,
    TIDL_VER_MINOR, TIDL_VER_PATCH, 2, RPC_PORT_PARCEL_HEADER_LAN_CPP);
  } else {
    rpc_port_parcel_header_set_tag(header_, TIDL_VERSION);
  }

  if (!CheckPrivileges(port, static_cast<int>(MethodId::FindById))) {
    _E("Permission denied");
    RemoteException remote_except(RPC_PORT_ERROR_PERMISSION_DENIED, "Permission denied");
    UnitMap()
    .Write(-1571313492 /*[REMOTE_EXCEPTION]*/, remote_except)
    .Write(1355467489 /*[METHOD]*/, static_cast<int>(MethodId::__Result))
    .Serialize(parcel_);
  } else {
    std::string id;
    unit_map.Read(3355 /*id*/, id);

    TizenEntityView v;

    try {
      auto ret_ = FindById(id, v);
      UnitMap()
      .Write(1497479973 /*[RESULT]*/, ret_)
      .Write(118 /*v*/, v)
      .Write(1355467489 /*[METHOD]*/, static_cast<int>(MethodId::__Result))
      .Serialize(parcel_);

      } catch (const RemoteException& e) {
      _E("Exception occurs. cause(%d), message(%s)", e.GetCause(), e.GetMessage().c_str());
      UnitMap()
      .Write(-1571313492 /*[REMOTE_EXCEPTION]*/, e)
      .Write(1355467489 /*[METHOD]*/, static_cast<int>(MethodId::__Result))
      .Serialize(parcel_);
    }
  }

  if (GetContext() != nullptr)
    TizenActionView_context_->SendResult(GetContext(), parcel_);
  else
    rpc_port_parcel_send(parcel_, port);
  rpc_port_parcel_destroy(parcel_);
}

