void TizenActionView::ServiceBase::DispatchToPresentation(rpc_port_h port, rpc_port_h callback_port, int seq_num, const UnitMap& unit_map) {
  rpc_port_parcel_h parcel_;
  rpc_port_parcel_create(&parcel_);

  rpc_port_parcel_header_h header_;
  rpc_port_parcel_get_header(parcel_, &header_);
  rpc_port_parcel_header_set_seq_num(header_, seq_num);
  if (dl_rpc_port_parcel_header_set_tag_ex) {
    dl_rpc_port_parcel_header_set_tag_ex(header_, TIDL_VER_MAJOR,
    TIDL_VER_MINOR, TIDL_VER_PATCH, 2, RPC_PORT_PARCEL_HEADER_LAN_CPP);
  } else {
    rpc_port_parcel_header_set_tag(header_, TIDL_VERSION);
  }

  if (!CheckPrivileges(port, static_cast<int>(MethodId::ToPresentation))) {
    _E("Permission denied");
    RemoteException remote_except(RPC_PORT_ERROR_PERMISSION_DENIED, "Permission denied");
    UnitMap()
    .Write(-1571313492 /*[REMOTE_EXCEPTION]*/, remote_except)
    .Write(1355467489 /*[METHOD]*/, static_cast<int>(MethodId::__Result))
    .Serialize(parcel_);
  } else {
    TizenEntityView view;
    unit_map.Read(3619493 /*view*/, view);

    TizenEntityPresentation result;

    try {
      auto ret_ = ToPresentation(view, result);
      UnitMap()
      .Write(1497479973 /*[RESULT]*/, ret_)
      .Write(-934426595 /*result*/, result)
      .Write(1355467489 /*[METHOD]*/, static_cast<int>(MethodId::__Result))
      .Serialize(parcel_);

      } catch (const RemoteException& e) {
      _E("Exception occurs. cause(%d), message(%s)", e.GetCause(), e.GetMessage().c_str());
      UnitMap()
      .Write(-1571313492 /*[REMOTE_EXCEPTION]*/, e)
      .Write(1355467489 /*[METHOD]*/, static_cast<int>(MethodId::__Result))
      .Serialize(parcel_);
    }
  }

  if (GetContext() != nullptr)
    TizenActionView_context_->SendResult(GetContext(), parcel_);
  else
    rpc_port_parcel_send(parcel_, port);
  rpc_port_parcel_destroy(parcel_);
}

void TizenActionView::ServiceBase::SetContext(void* context) {
  context_ = context;
}

void* TizenActionView::ServiceBase::GetContext() const {
  return context_;
}

TizenActionView::TizenActionView() {
  _W("TizenActionView ctor");
  int ret = rpc_port_stub_create(&stub_, "TizenActionView");
  if (ret != RPC_PORT_ERROR_NONE) {
    _E("Failed to create stub. error(%d)", ret);
    throw InvalidIOException();
  }
  rpc_port_stub_add_connected_event_cb(stub_, OnConnectedCb, this);
  rpc_port_stub_add_disconnected_event_cb(stub_, OnDisconnectedCb, this);
  rpc_port_stub_add_received_event_cb(stub_, OnReceivedCb, this);

  TizenActionView_context_ = std::make_unique<LocalExecution>("TizenActionView", this);
}

TizenActionView::~TizenActionView() {
  _W("TizenActionView dtor");
  for (auto& service : services_) {
    if(!service->GetInstance().empty())
    service->OnTerminate();

    if (TizenActionView_context_ && service->GetContext())
      TizenActionView_context_->Disconnect(service->GetContext());
  }

  TizenActionView_context_.reset();
  if (stub_ != nullptr)
    rpc_port_stub_destroy(stub_);
}

void TizenActionView::Listen(std::shared_ptr<TizenActionView::ServiceBase::Factory> service_factory) {
  service_factory_ = std::move(service_factory);
  int ret = rpc_port_stub_listen(stub_);
  if (ret != RPC_PORT_ERROR_NONE) {
    _E("Failed to listen stub. error(%d)", ret);
    if (ret == RPC_PORT_ERROR_INVALID_PARAMETER || ret == RPC_PORT_ERROR_IO_ERROR)
      throw InvalidIOException();
  }

  TizenActionView_context_->SetListening(true);
}
void TizenActionView::OnConnectedCb(const char* sender, const char* instance, void* user_data) {
  auto* handle = static_cast<TizenActionView*>(user_data);
  auto service = handle->service_factory_->CreateService(sender, instance);

  service->SetParent(handle);
  rpc_port_h port;
  int ret = rpc_port_stub_get_port(handle->stub_, RPC_PORT_PORT_CALLBACK, instance, &port);
  if (ret != RPC_PORT_ERROR_NONE) {
    _E("Failed to get port. error(%d)", ret);
    return;
  }

  service->SetPort(port);
  service->OnCreate();
  handle->services_.emplace_back(std::move(service));
}

void TizenActionView::OnDisconnectedCb(const char* sender, const char* instance, void* user_data) {
  auto* handle = static_cast<TizenActionView*>(user_data);
  auto iter = handle->services_.begin();
  while (iter != handle->services_.end()) {
    if ((*iter)->GetInstance() == instance) {
      (*iter)->OnTerminate();
      iter = handle->services_.erase(iter);
      break;
    }

    iter++;
  }
}

int TizenActionView::OnReceivedCb(const char* sender, const char* instance, rpc_port_h port, void* user_data) {
  auto* handle = static_cast<TizenActionView*>(user_data);
  std::shared_ptr<ServiceBase> service;
  for (auto& iter : handle->services_) {
    if (iter->GetInstance() == instance) {
      service = iter;
      break;
    }
  }

  if (service.get() == nullptr) {
    _E("Failed to find TizenActionView context. instance(%s)", instance);
    return -1;
  }

  rpc_port_h callback_port;
  int ret = rpc_port_stub_get_port(handle->stub_, RPC_PORT_PORT_CALLBACK, instance, &callback_port);
  if (ret != 0) {
    _E("Failed to get callback port. error(%d)", ret);
    return -1;
  }

  rpc_port_parcel_h parcel;
  ret = rpc_port_parcel_create_from_port(&parcel, port);
  if (ret != 0) {
    _E("Failed to create parcel from port. error(%d)", ret);
    return ret;
  }

  return service->Dispatch(port, callback_port, parcel, service);
}

void TizenActionView::OnLocalConnected(void* context, const std::string& sender, const std::string& instance, bool sync) {
  auto service = service_factory_->CreateService(sender, instance);
  service->SetParent(this);
  service->SetContext(context);
  service->OnCreate();
  services_.emplace_back(std::move(service));
  TizenActionView_context_->Connect(context, sync);
}

void TizenActionView::OnLocalDisconnected(void* context, const std::string& sender, const std::string& instance) {
  auto iter = services_.begin();
  while (iter != services_.end()) {
    if ((*iter)->GetInstance() == instance) {
      (*iter)->OnTerminate();
      iter = services_.erase(iter);
      break;
    }

    iter++;
  }

  TizenActionView_context_->Disconnect(context);
}

void TizenActionView::OnLocalReceived(void* context, rpc_port_parcel_h parcel) {
  std::shared_ptr<ServiceBase> service;
  for (auto& iter : services_) {
    if (iter->GetContext() == context) {
      service = iter;
      break;
    }
  }

  if (service.get() == nullptr) {
    _E("Failed to find TizenActionView context. context(%p)", context);
    return;
  }

  service->Dispatch(nullptr, nullptr, parcel, service);
}

